<template>

    <div class="container"></div>
        <h1>Formulario Cliente</h1>
        <form action="" id="student-form" @submit.prevent="guardar">
            <div class="form-group">
                <label for="codigo">codigo:</label>
                <input type="text" id="codigo" name="codigo" required v-model="codigo">
            </div>
              <div class="form-group">
                <label for="nombre">nombre:</label>
                <input type="text" id="cnombre" name="nombre" required v-model="nombre">
            </div>
              <div class="form-group">
                <label for="correo">correo:</label>
                <input type="text" id="correo" name="correo" required v-model="correo">
            </div>
              <div class="form-group">
                <label for="telefono">telefono:</label>
                <input type="text" id="telefono" name="telefono" required v-model="telefono">
            </div>
            <button type="submit">Guardar</button>
            <button type="button">Eliminar</button>
            <button type="button">Actualizar</button>
            <button type="button">Consultar</button>

        </form>        

</template>
<script>

import axios from 'axios';

export default{

    data(){

        return{
             codigo:"",
            nombre:"",
            correo:"",
            telefono:""
        };
           
    }, 
    methods:{
        guardar(){
            axios.post("http://localhost:8080/api/clientes",{
                codigo:this.codigo,
                nombre:this.nombre,
                correo:this.correo,
                telefono:this.telefono
            })
            .then((response)=>{
            console.log("cliennte registrado exitosamente",response.data);
            alert("usuario registrado");
            this.codigo="";
            this.nombre="";
            this.codigo="";
            this.telefono="";
            })
            .catch((error)=>{
                console.error("error al registrar el cliente",error);
            });
            
        },
   },

};

</script>

